const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体示意' },
      { kind: 'text', payload: '由静止释放（v₀ = 0）' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: '速度 v 与重力加速度 g 均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var cx = w * 0.42;
    var ballY = h * 0.34;
    var r = Math.max(26, Math.min(54, Math.min(w, h) * 0.085));
    var arrowLen = Math.max(80, h * 0.20);
    var vX = cx;
    var vY1 = ballY + r + 18;
    var vY2 = vY1 + arrowLen;
    var gX = w * 0.68;
    var gY1 = ballY - r * 0.2;
    var gY2 = gY1 + arrowLen;
    var headW = 9;
    var headL = 16;

    function shaftCmds(x, y1, y2) {
      return [['M', x, y1], ['L', x, y2]];
    }
    function headCmds(x, y2) {
      return [['M', x, y2], ['L', x - headW, y2 - headL], ['L', x + headW, y2 - headL], ['Z']];
    }

    var ballPath = visualSdk.circle(cx, ballY, r);
    var vShaft = shaftCmds(vX, vY1, vY2);
    var vHead = headCmds(vX, vY2);
    var gShaft = shaftCmds(gX, gY1, gY2);
    var gHead = headCmds(gX, gY2);

    var fallX = cx - r * 1.7;
    var fallCmds = [];
    var fallStart = ballY + r * 0.2;
    var fallEnd = h * 0.82;
    for (var y = fallStart; y < fallEnd; y += 18) {
      fallCmds.push(['M', fallX, y]);
      fallCmds.push(['L', fallX, Math.min(y + 9, fallEnd)]);
    }

    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'ball', commands: ballPath },
        { id: 'fall-guide', commands: fallCmds },
        { id: 'v-shaft', commands: vShaft },
        { id: 'v-head', commands: vHead },
        { id: 'g-shaft', commands: gShaft },
        { id: 'g-head', commands: gHead }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'fall-guide', fill: '#94a3b8', stroke: { width: 2 } },
        { type: 'path', pathId: 'ball', fill: '#bfdbfe', stroke: { width: 3 } },
        { type: 'path', pathId: 'v-shaft', fill: '#2563eb', stroke: { width: 5 } },
        { type: 'path', pathId: 'v-head', fill: '#2563eb', stroke: { width: 1 } },
        { type: 'path', pathId: 'g-shaft', fill: '#dc2626', stroke: { width: 5 } },
        { type: 'path', pathId: 'g-head', fill: '#dc2626', stroke: { width: 1 } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: w / 2, y: h * 0.10 }, hAlign: 'center', vAlign: 'middle', color: '#0f172a' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx, y: ballY - r - 16 }, hAlign: 'center', vAlign: 'bottom', color: '#334155' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: vX - 14, y: (vY1 + vY2) / 2 }, hAlign: 'right', vAlign: 'middle', color: '#2563eb' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: gX + 14, y: (gY1 + gY2) / 2 }, hAlign: 'left', vAlign: 'middle', color: '#dc2626' },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: w / 2, y: h * 0.90 }, hAlign: 'center', vAlign: 'middle', color: '#334155' }
      ]}
    };
  }
};
